/* Primeiro nó depois do webhook: confere o segredo compartilhado e segue com
   o corpo do pedido. O token vai no header e nunca na URL — URL aparece em
   log de proxy. Sem `NUTRIELIVE_TOKEN` configurado no n8n, o fluxo PARA:
   aceitar qualquer chamada deixaria qualquer um gravar plano alheio. */
const esperado = $env.NUTRIELIVE_TOKEN;
if (!esperado) throw new Error('NUTRIELIVE_TOKEN não está configurado neste n8n.');

const recebido = $input.first().json.headers?.['x-nutrielive-token'];
if (!recebido || recebido !== esperado) throw new Error('Token do webhook inválido.');

return [{ json: $input.first().json.body }];

/* Modelo às vezes embrulha o JSON em cerca de código, mesmo mandado não
   fazer. Em vez de falhar o fluxo por causa de três acentos graves,
   descasca e tenta de novo. */
const t = String($input.first().json.text ?? $input.first().json.output ?? '').trim();
const limpo = t.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
try { return [{ json: JSON.parse(limpo) }]; }
catch (e) { throw new Error('O modelo não devolveu JSON válido: ' + e.message); }

/* =========================================================================
   Monta o PlanoAlimentar completo a partir do que o modelo escolheu.

   O modelo devolve SÓ escolha e quantidade:
     { dias: [ { refeicoes: [ { tipo, titulo, preparo: [..],
                                itens: [ { alimentoId, gramas } ] } ] } ] }

   Tudo o que é número sai daqui, da tabela que veio no payload:
   kcal e macros de cada item, de cada refeição e de cada dia; os totais do
   resumo; e o preço da lista de compras. Modelo erra soma e inventa preço;
   `kcal100 * gramas / 100` não erra.

   Se o modelo devolver um alimento que não está na lista permitida, o item é
   DESCARTADO aqui, antes de sair do fluxo. O servidor recusaria o plano
   inteiro por violação de restrição (`validarPlano`), e perder um plano
   bom por causa de um item inventado é desperdício.
   ========================================================================= */
const entrada = $('Conferir token').first().json;
const bruto = $input.first().json;

const porId = new Map(entrada.alimentosPermitidos.map((a) => [a.id, a]));

const HORARIO = {
  cafe: ['Café da manhã', '07:00'],
  lanche_manha: ['Lanche da manhã', '10:00'],
  almoco: ['Almoço', '12:30'],
  lanche_tarde: ['Lanche da tarde', '16:00'],
  jantar: ['Jantar', '19:30'],
  ceia: ['Ceia', '21:30']
};
const ORDEM = ['cafe', 'lanche_manha', 'almoco', 'lanche_tarde', 'jantar', 'ceia'];

/* ---------------------- higiene de texto livre --------------------------
   O servidor varre título, nome de item e passo de preparo contra os termos
   das restrições, e descarta o PLANO INTEIRO se achar um. O modelo erra
   justamente aqui: escolhe o alimento certo e escreve "Iogurte com fruta"
   no título de um plano sem lactose. Então o texto é limpo antes de sair.
   `termosProibidos` é a mesma lista que a validação usa (`termosBloqueados`
   em seguranca.ts), então não há como as duas discordarem. */
const proibidos = (entrada.restricoes.termosProibidos || []).filter(Boolean);
const semAcento = (t) => String(t || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const violaTexto = (t) => {
  const n = semAcento(t);
  return proibidos.some((p) => new RegExp('(^|[^a-z0-9])' + p.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '([^a-z0-9]|$)').test(n));
};
const textoSeguro = (t, reserva) => (t && !violaTexto(t) ? String(t) : reserva);

const r1 = (n) => Math.round(n * 10) / 10;
const somaMacros = (lista) => lista.reduce(
  (t, x) => ({ protein: r1(t.protein + x.macros.protein), carb: r1(t.carb + x.macros.carb), fat: r1(t.fat + x.macros.fat) }),
  { protein: 0, carb: 0, fat: 0 }
);

/* kcal SEMPRE derivada dos macros (4/4/9), nunca do `kcal100` do alimento.
   O servidor confere item por item se `kcal` bate com `4P + 4C + 9G` com
   tolerância de 1 kcal (`validarPlano`, tolItem). Somar `kcal100 * g / 100`
   dá um número parecido e não idêntico — e um plano inteiro seria recusado
   por uma diferença de arredondamento. O `kcal100` do payload serve para o
   modelo escolher porção, não para fechar conta. */
const energia = (m) => Math.round(m.protein * 4 + m.carb * 4 + m.fat * 9);

/* data do dia N, contada a partir da dataBase que o app mandou: o fluxo não
   usa o relógio do n8n, que pode estar em outro fuso. */
const dataDoDia = (n) => {
  const base = new Date(entrada.dataBase + 'T12:00:00.000Z');
  base.setUTCDate(base.getUTCDate() + (n - 1));
  return base.toISOString().slice(0, 10);
};

/* ----------------------- calibragem do dia ------------------------------
   Esta é a parte que decide se o fluxo serve para algo.

   O servidor recusa o plano INTEIRO quando um dia sai da tolerância de
   calorias (`validarPlano`, `toleranciaKcal`, 5% por padrão). E um modelo de
   linguagem pedido para "fechar em 1780 kcal escolhendo gramas" erra de 10%
   a 20% com naturalidade — nos nossos testes, 1519, 1917 e 2021 kcal para
   uma meta de 1780. Sem calibrar, quase todo plano gerado seria descartado e
   a pessoa veria "a IA não conseguiu" na maioria das tentativas.

   Então o modelo decide O QUE comer e o fluxo acerta QUANTO: multiplica os
   gramas pelo fator que falta, respeitando `min`, `max` e `passo` de cada
   alimento. Alimento que bateu no teto para de ajudar, daí repetir algumas
   vezes em vez de uma conta só. Para quando entra na faixa ou quando parou
   de melhorar — insistir além disso só moeria número.

   Note a ordem: a calibragem é por DIA, porque a tolerância é por dia. */
function calibrar(refeicoes, metaKcal, tolPct) {
  const dentro = (k) => Math.abs(k - metaKcal) <= metaKcal * tolPct;
  const totalDe = () => refeicoes.reduce(
    (t, r) => t + r.itens.reduce((s, it) => s + it.gramasCalc * it.kcalPorGrama, 0), 0);

  let total = totalDe();
  if (!total || dentro(total)) return;

  let melhorDiferenca = Math.abs(total - metaKcal);
  for (let volta = 0; volta < 10; volta++) {
    const fator = metaKcal / total;
    for (const r of refeicoes) {
      for (const it of r.itens) {
        const bruto = it.gramasCalc * fator;
        const passo = it.passo > 0 ? it.passo : 1;
        it.gramasCalc = Math.max(it.min, Math.min(it.max, Math.round(bruto / passo) * passo));
      }
    }
    total = totalDe();
    const diferenca = Math.abs(total - metaKcal);
    if (dentro(total)) return;
    /* Parou de melhorar: todos os alimentos no teto ou no piso. */
    if (diferenca >= melhorDiferenca - 0.5) return;
    melhorDiferenca = diferenca;
  }
}

const diasCrus = Array.isArray(bruto?.dias) ? bruto.dias : [];
if (!diasCrus.length) throw new Error('O modelo não devolveu nenhum dia.');

const dias = diasCrus.map((diaCru, i) => {
  const refeicoesCruas = Array.isArray(diaCru?.refeicoes) ? diaCru.refeicoes : [];

  const refeicoes = refeicoesCruas
    .filter((r) => HORARIO[r?.tipo])
    .sort((a, b) => ORDEM.indexOf(a.tipo) - ORDEM.indexOf(b.tipo))
    .map((refCrua) => {
      /* Primeiro só a escolha, com os números que a calibragem usa. O item
         final é montado depois, já com os gramas calibrados. */
      const itens = (Array.isArray(refCrua.itens) ? refCrua.itens : [])
        .map((itemCru) => {
          const a = porId.get(itemCru?.alimentoId);
          if (!a) return null;                       /* inventado: fora */
          const passo = a.passo > 0 ? a.passo : 1;
          const pedido = Math.round(Number(itemCru.gramas) || 0);
          const gramas = Math.max(a.min, Math.min(a.max, Math.round(pedido / passo) * passo));
          if (gramas <= 0) return null;
          return {
            a, min: a.min, max: a.max, passo,
            gramasCalc: gramas,
            /* kcal por grama derivada dos macros, igual ao servidor. */
            kcalPorGrama: (a.proteina100 * 4 + a.carbo100 * 4 + a.gordura100 * 9) / 100
          };
        })
        .filter(Boolean);

      if (!itens.length) return null;
      const [rotulo, horario] = HORARIO[refCrua.tipo];
      return {
        tipo: refCrua.tipo,
        rotulo,
        horario,
        titulo: textoSeguro(String(refCrua.titulo || '').slice(0, 120), rotulo),
        itens,
        /* Passo que menciona termo proibido sai da lista: o passo some, o
           plano fica. Melhor uma receita com um passo a menos que nenhum
           plano para quem pediu. */
        preparo: (Array.isArray(refCrua.preparo) ? refCrua.preparo : [])
          .map((p) => String(p).slice(0, 300))
          .filter((p) => !violaTexto(p))
          .slice(0, 8)
      };
    })
    .filter(Boolean);

  if (!refeicoes.length) throw new Error(`O dia ${i + 1} ficou sem nenhuma refeição aproveitável.`);

  calibrar(refeicoes, entrada.metas.kcal, entrada.metas.toleranciaKcalPct / 100);

  /* Agora os gramas são finais: fecha item, refeição e dia, sempre com a
     kcal derivada dos macros. */
  const fechadas = refeicoes.map((r) => {
    const itens = r.itens.map((it) => {
      const f = it.gramasCalc / 100;
      const macros = {
        protein: r1(it.a.proteina100 * f), carb: r1(it.a.carbo100 * f), fat: r1(it.a.gordura100 * f)
      };
      return {
        alimentoId: it.a.id,
        nome: it.a.nome,
        gramas: it.gramasCalc,
        porcao: `${it.gramasCalc} g (${it.a.medida})`,
        kcal: energia(macros),
        macros
      };
    });
    const macrosRef = somaMacros(itens);
    return {
      tipo: r.tipo, rotulo: r.rotulo, horario: r.horario, titulo: r.titulo,
      kcal: energia(macrosRef), macros: macrosRef, itens, preparo: r.preparo
    };
  });

  const macrosDia = somaMacros(fechadas);
  return {
    dia: i + 1,
    data: dataDoDia(i + 1),
    kcal: energia(macrosDia),
    macros: macrosDia,
    refeicoes: fechadas
  };
});

/* ---------------------------- lista de compras -------------------------- */
/* Soma os gramas de todos os dias por alimento, com 10 % de folga: ninguém
   compra exatamente o que vai comer. O preço sai de centavosPorKg. */
const soma = new Map();
for (const d of dias) {
  for (const r of d.refeicoes) {
    for (const it of r.itens) {
      soma.set(it.alimentoId, (soma.get(it.alimentoId) || 0) + it.gramas);
    }
  }
}
const quantidade = (g) => g >= 1000
  ? `${(Math.round(g / 100) / 10).toFixed(1).replace('.', ',')} kg`
  : `${Math.round(g / 10) * 10} g`;

const items = [...soma.entries()].map(([id, gramas]) => {
  const a = porId.get(id);
  const comprar = Math.ceil((gramas * 1.1) / 10) * 10;
  return {
    group: a.setor,
    name: a.nomeDeCompra,
    qty: quantidade(comprar),
    cents: Math.round((comprar / 1000) * a.centavosPorKg),
    done: false
  };
}).sort((x, y) => x.group.localeCompare(y.group, 'pt-BR') || x.name.localeCompare(y.name, 'pt-BR'));

/* segunda-feira da semana da dataBase */
const d0 = new Date(entrada.dataBase + 'T12:00:00.000Z');
const diaSemana = (d0.getUTCDay() + 6) % 7;
d0.setUTCDate(d0.getUTCDate() - diaSemana);
const weekStart = d0.toISOString().slice(0, 10);

/* -------------------------------- resumo -------------------------------- */
const kcalMedia = Math.round(dias.reduce((t, d) => t + d.kcal, 0) / dias.length);
const macrosMedia = {
  protein: r1(dias.reduce((t, d) => t + d.macros.protein, 0) / dias.length),
  carb: r1(dias.reduce((t, d) => t + d.macros.carb, 0) / dias.length),
  fat: r1(dias.reduce((t, d) => t + d.macros.fat, 0) / dias.length)
};

return [{
  json: {
    jobId: entrada.jobId,
    status: 'concluido',
    output: {
      tipo: 'plano_alimentar',
      versao: 1,
      titulo: textoSeguro(String(bruto?.titulo || '').slice(0, 160), `Plano de ${dias.length} ${dias.length === 1 ? 'dia' : 'dias'}`),
      dias,
      metas: {
        kcal: entrada.metas.kcal,
        macros: entrada.metas.macros,
        aguaMl: entrada.metas.aguaMl,
        metodo: 'metas do perfil, calculadas pelo app e repassadas ao fluxo',
        tmb: null,
        fatorAtividade: 1
      },
      resumo: {
        kcalMeta: entrada.metas.kcal,
        kcalMedia,
        macrosMeta: entrada.metas.macros,
        macrosMedia,
        desvioKcalPct: entrada.metas.kcal
          ? Math.round(((kcalMedia - entrada.metas.kcal) / entrada.metas.kcal) * 1000) / 10
          : 0
      },
      contexto: {
        objetivo: entrada.perfil.objetivo,
        estiloAlimentar: entrada.perfil.estiloAlimentar || 'tudo',
        restricoesAplicadas: entrada.restricoes.declaradas,
        etiquetasBloqueadas: entrada.restricoes.etiquetasBloqueadas,
        evitados: entrada.restricoes.evitar
      },
      listaDeCompras: { weekStart, estimatedCents: items.reduce((s, i) => s + i.cents, 0), items },
      receitas: [],
      avisos: [],
      /* Com nutricionista vinculada o plano nasce rascunho, para ela revisar
         antes de o paciente ver. Sem ela, nasce ativo e é material
         educativo, nunca prescrição. */
      status: entrada.pedido.temNutricionistaVinculada ? 'rascunho' : 'ativo',
      materialEducativo: !entrada.pedido.temNutricionistaVinculada,
      gerado: { driver: 'n8n', em: new Date().toISOString(), semente: entrada.semente }
    },
    executionId: $execution.id,
    tokensIn: $('Modelo').first().json?.tokenUsage?.promptTokens ?? null,
    tokensOut: $('Modelo').first().json?.tokenUsage?.completionTokens ?? null
  }
}];

/* Caminho de erro: o app precisa saber que o job morreu, senão ele fica
   "processando" para sempre e a pessoa olha uma tela girando. A mensagem vai
   em português porque é ela que aparece na tela — e em /admin/ia. */
const erro = $input.first().json;
let jobId = null;
try { jobId = $('Conferir token').first().json.jobId; } catch (e) {}
if (!jobId) { try { jobId = $('Webhook').first().json.body?.jobId; } catch (e) {} }

return [{
  json: {
    jobId,
    status: 'erro',
    error: 'A geração por IA não terminou: ' + String(erro?.message || erro?.error || 'falha no fluxo do n8n'),
    executionId: $execution.id
  }
}];
